'use strict';
let packOpening=false,packRevealTimer;
const rarityOrder={'Common':0,'Rare':1,'Super Rare':2,'Ultra Rare':3,'Secret Rare':4};
function sortPack(list){return [...list].sort((a,b)=>(rarityOrder[a.rarity]||0)-(rarityOrder[b.rarity]||0));}
function startPackReveal(list,packName=activeSet().name){
 packOpening=true;const best=list.at(-1),tone=rarityClass(best);const dialog=$('#packReveal');
 dialog.className='pack-reveal '+tone;
 $('#packRevealBody').innerHTML=`<div class="reveal-heading"><span class="eyebrow">${esc(packName)}</span><h2>Tu próxima sorpresa.</h2><p id="revealHint" role="status">Abriendo el sobre…</p></div><div id="sealedStage" class="sealed-stage"><div class="foil-pack"><div class="foil-top"></div><div class="cut-line"></div><svg class="millennium-art" viewBox="0 0 200 300" aria-hidden="true"><defs><linearGradient id="goldFoil" x2="1" y2="1"><stop stop-color="#fff0b4"/><stop offset=".4" stop-color="#ad7930"/><stop offset=".65" stop-color="#ffe6a0"/><stop offset="1" stop-color="#7d4b1d"/></linearGradient></defs><g fill="none" stroke="url(#goldFoil)"><path d="M100 20 186 260H14Z" stroke-width="3"/><path d="M100 44 167 247H33Z" stroke-width="1"/><path d="M100 260 100 294M14 260 100 294 186 260" stroke-width="3"/><circle cx="100" cy="159" r="56" stroke-width="1"/><path d="M43 158Q100 108 157 158Q100 207 43 158Z" stroke-width="5"/><path d="M47 149Q85 115 142 140M151 159 166 145M53 175 42 195 75 187M116 181Q139 210 114 218" stroke-width="5"/><path d="M100 101V88M100 228V217M30 159H18M182 159H170" stroke-width="2"/></g><ellipse cx="100" cy="158" rx="17" ry="26" fill="url(#goldFoil)"/><ellipse cx="100" cy="158" rx="6" ry="20" fill="#160d21"/></svg></div><div class="pack-aura"></div></div><div id="revealCards" class="reveal-cards" hidden>${list.map((c,i)=>`<button class="flip-card ${rarityClass(c)}" data-reveal-index="${i}" aria-label="Revelar carta ${i+1}" aria-pressed="false"><span class="flip-inner"><span class="card-back"><img src="assets/card-back.jpg" alt="Reverso de carta Yu-Gi-Oh!" draggable="false"></span><span class="card-front"><img src="${esc(image(c))}" alt=""><span>${esc(c.name_es)}</span><small>${esc(names[c.rarity])}</small></span></span></button>`).join('')}</div><div class="reveal-actions"><button id="revealAll" hidden>Revelar todas</button><button id="finishReveal" class="quiet">Continuar</button></div><p class="micro">Las ${list.length} cartas ya están guardadas en tu colección.</p>`;
 dialog.showModal();
 const show=()=>{$('#sealedStage').hidden=true;$('#revealCards').hidden=false;$('#revealAll').hidden=false;$('#revealHint').textContent='Tocá cada carta para revelarla · de menor a mayor rareza';};
 packRevealTimer=setTimeout(show,matchMedia('(prefers-reduced-motion: reduce)').matches?0:1500);
 function reveal(button){if(button.classList.contains('flipped'))return;const c=list[Number(button.dataset.revealIndex)];button.classList.add('flipped');button.setAttribute('aria-pressed','true');button.setAttribute('aria-label',c.name_es+' · '+names[c.rarity]);button.querySelector('.card-front img').alt=c.name_en;const count=dialog.querySelectorAll('.flipped').length;$('#revealHint').textContent=count===list.length?'¡Sobre completo! Todas las cartas están en tu colección.':`${count} de ${list.length} cartas reveladas`;if(count===list.length)$('#revealAll').hidden=true;}
 $('#revealCards').onclick=e=>{const b=e.target.closest('[data-reveal-index]');if(b)reveal(b);};
 $('#revealAll').onclick=()=>dialog.querySelectorAll('[data-reveal-index]').forEach(reveal);
 $('#finishReveal').onclick=()=>dialog.close();
}
$('#packReveal').addEventListener('close',()=>{clearTimeout(packRevealTimer);packOpening=false;if(view==='sobres')$('#results').scrollIntoView({behavior:'smooth',block:'start'});});
